function Icon({name,size=20,...props}: {name:IconName;size?:number;className?:string}) {
 const paths: Record<IconName,ReactNode> = {
 grid:<><rect x=\"3\" y=\"3\" width=\"7\" height=\"7\" rx=\"1.8\"/><rect x=\"14\" y=\"3\" width=\"7\" height=\"7\" rx=\"1.8\"/><rect x=\"3\" y=\"14\" width=\"7\" height=\"7\" rx=\"1.8\"/><rect x=\"14\" y=\"14\" width=\"7\" height=\"7\" rx=\"1.8\"/></>,
 chart:<><path d=\"M4 4v16h17M8 15l4-5 4 3 5-7\"/></>, users:<><path d=\"M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/></>,
