 search:<><circle cx=\"10.5\" cy=\"10.5\" r=\"6.5\"/><path d=\"m16 16 4 4\"/></>, bell:<><path d=\"M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4\"/></>, chevron:<path d=\"m9 5 7 7-7 7\"/>,arrow:<path d=\"M7 17 17 7M7 7h10v10\"/>,plus:<path d=\"M12 5v14M5 12h14\"/>,download:<><path d=\"M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5\"/></>,calendar:<><rect x=\"3\" y=\"5\" width=\"18\" height=\"16\" rx=\"3\"/><path d=\"M7 3v4m10-4v4M3 11h18\"/></>,sliders:<><path d=\"M4 7h9m4 0h3M4 17h3m4 0h9\"/><circle cx=\"15\" cy=\"7\" r=\"2\"/><circle cx=\"9\" cy=\"17\" r=\"2\"/></>,grip:<>{[5,12,19].map(y=><g key={y}><circle cx=\"9\" cy={y} r=\".9\" fill=\"currentColor\"/><circle cx=\"15\" cy={y} r=\".9\" fill=\"currentColor\"/></g>)}</>,close:<path d=\"m6 6 12 12M6 18 18 6\"/>,check:<path d=\"m5 12 4 4L19 6\"/>,more:<>{[5,12,19].map(x=><circle key={x} cx={x} cy=\"12\" r=\"1\" fill=\"currentColor\"/>)}</>,external:<><path d=\"M14 3h7v7m0-7L10 14M10 3H4v17h17v-6\"/></>,wallet:<><rect x=\"3\" y=\"5\" width=\"18\" height=\"15\" rx=\"3\"/><path d=\"M3 8V5a2 2 0 0 1 2-2h12m4 8h-5v5h5M17 13.5h.01\"/></>,globe:<><circle cx=\"12\" cy=\"12\" r=\"9\"/><ellipse cx=\"12\" cy=\"12\" rx=\"4\" ry=\"9\"/><path d=\"M3 12h18\"/></>,target:<><circle cx=\"12\" cy=\"12\" r=\"9\"/><circle cx=\"12\" cy=\"12\" r=\"5\"/><circle cx=\"12\" cy=\"12\" r=\"1\"/></>,logout:<><path d=\"M9 4H4v16h5m6-13 5 5-5 5M9 12h11\"/></>
 };
 return <svg width={size} height={size} viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"1.65\" strokeLinecap=\"round\" strokeLinejoin=\"round\" {...props}>{paths[name]}</svg>;
}
type Widget = {id:string;type:string;span:number};
const initialWidgets:Widget[]=[{id:'revenue',type:'revenue',span:3},{id:'orders',type:'orders',span:3},{id:'customers',type:'customers',span:3},{id:'conversion',type:'conversion',span:3},{id:'sales',type:'sales',span:8},{id:'traffic',type:'traffic',span:4},{id:'transactions',type:'transactions',span:8},{id:'goal',type:'goal',span:4}];
const widgetNames:Record<string,string>={revenue:'Общая выручка',orders:'Заказы',customers:'Новые клиенты',conversion:'Конверсия',sales:'Динамика выручки',traffic:'Источники трафика',transactions:'Последние заказы',goal:'Цель месяца',visitors:'Посетители сайта'};
