function readLayout():Widget[]{try{const value=JSON.parse(localStorage.getItem('forma-layout')||'null');return Array.isArray(value)&&value.every(v=>v.id&&widgetNames[v.type]&&[3,4,6,8,12].includes(v.span))?value:initialWidgets;}catch{return initialWidgets;}}
function Spark({variant=0}: {variant?:number}) {const paths=['M0 35 12 31 22 34 32 24 42 29 52 20 62 24 72 12 82 17 92 7 104 10','M0 34 12 34 22 26 32 28 42 19 52 24 62 14 72 18 82 9 92 12 104 4','M0 36 10 29 20 32 30 22 40 28 50 19 60 21 70 12 80 16 90 9 104 5','M0 31 12 25 22 28 32 20 42 24 52 17 62 21 72 13 82 16 92 6 104 9'];return <svg className=\"spark\" viewBox=\"0 0 106 46\"><defs><linearGradient id={"'`spark${variant}`} x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#84b799" stopOpacity=".18"/><stop offset="100%" stopColor="#84b799" stopOpacity="0"/></linearGradient></defs><path d={`${paths[variant%4]}V46H0Z`} fill={`url(#spark${variant})`}/><path d={paths[variant%4]} fill="none" stroke="#72a586" strokeWidth="1.8" strokeLinejoin="round"/></svg>}
function RevenueChart({period}:{period:string}) {
 const [point,setPoint]=useState<number|null>(null);const [chartType,setChartType]=useState('"'Выручка');
 return <><div className=\"card-heading\"><div><h3>Динамика выручки</h3><p>Ваш бизнес в цифрах, день за днём</p></div><select className=\"small-select\" value={chartType} onChange={e=>setChartType(e.target.value)}><option>Выручка</option><option>Заказы</option></select></div><div className=\"chart-summary\"><strong>{chartType==='Выручка'?(period==='week'?'₽ 324 850':'₽ 1 284 650'):'1 842'}</strong><span className=\"growth\"><Icon name=\"arrow\" size={13}/>18,6%</span><span className=\"muted\">к прошлому {period==='week'?'периоду':'месяцу'}</span></div><div className=\"line-chart\"><div className=\"chart-y\">{(chartType==='Выручка'?['60 тыс.','45 тыс.','30 тыс.','15 тыс.','0']:['100','75','50','25','0']).map(t=><span key={t}>{t}</span>)}</div><div className=\"chart-plot\" onMouseLeave={()=>setPoint(null)}><svg viewBox=\"0 0 640 190\" preserveAspectRatio=\"none\" aria-label=\"График выручки за июнь\"><defs><linearGradient id=\"chartFill\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stopColor=\"#b5cebc\" stopOpacity=\".45\"/><stop offset=\"1\" stopColor=\"#d7e6da\" stopOpacity=\".03\"/></linearGradient></defs>{[10,52,94,136,178].map(y=><line key={y} x1=\"0\" x2=\"640\" y1={y} y2={y} stroke=\"#ebeeeb\" strokeDasharray=\"3 4\"/>)}<path d=\"M0 150C12 150 15 127 29 130S50 148 63 130S80 131 94 119S108 131 122 119S141 131 155 106S175 119 188 103S208 121 223 95S241 105 256 84S275 94 289 75S306 82 321 68S339 98 354 82S372 96 387 65S404 65 420 47S438 61 453 43S469 61 484 38S506 48 519 29S538 43 551 24S572 35 585 19S608 38 621 13L640 8V190H0Z\" fill=\"url(#chartFill)\"/><path d=\"M0 162C23 159 25 144 45 151S73 140 94 145S113 133 135 139S157 121 178 131S201 119 223 126S245 108 267 119S287 106 309 115S333 106 354 117S377 95 398 109S419 93 441 103S465 85 486 95S510 84 532 92S553 77 575 88S611 69 640 76\" fill=\"none\" stroke=\"#c7ceca\" strokeWidth=\"2\" strokeDasharray=\"5 5\"/><path d=\"M0 150C12 150 15 127 29 130S50 148 63 130S80 131 94 119S108 131 122 119S141 131 155 106S175 119 188 103S208 121 223 95S241 105 256 84S275 94 289 75S306 82 321 68S339 98 354 82S372 96 387 65S404 65 420 47S438 61 453 43S469 61 484 38S506 48 519 29S538 43 551 24S572 35 585 19S608 38 621 13L640 8\" fill=\"none\" stroke=\"#6f9c7b\" strokeWidth=\"2.5\"/>{Array.from({length:30},(_,i)=><rect key={i} x={i*21.33} y=\"0\" width=\"21.33\" height=\"190\" fill=\"transparent\" onMouseMove={()=>setPoint(i)}/>)}{point"'!==null&&<><line x1={point*21.33+10} x2={point*21.33+10} y1="0" y2="190" stroke="#749e80" strokeDasharray="4 3"/><circle cx={point*21.33+10} cy={150-point*4.6} r="4" fill="#6f9c7b" stroke="white" strokeWidth="2"/></>}</svg>{point!==null&&<div className="chart-tooltip" style={{left:`${Math.min(75,point/30*100)}%`}}>{point+1} июня<strong>{chartType==='"'Выручка'?"'`₽ ${(28000+point*1040).toLocaleString('"'ru-RU')}"'`:45+point*2}</strong></div>}<div className="chart-x">{['"'1 июн','5 июн','10 июн','15 июн','20 июн','25 июн','30 июн'].map(t=><span key={t}>{t}</span>)}</div></div></div><div className=\"chart-legend\"><span><i className=\"legend-line green\"/>Текущий период</span><span><i className=\"legend-line dashed\"/>Предыдущий период</span></div></>;
}
function Traffic(){return <><div className=\"card-heading\"><div><h3>Источники трафика</h3><p>Откуда приходят ваши клиенты</p></div><Icon name=\"globe\" size={18}/></div><div className=\"donut-wrap\"><svg viewBox=\"0 0 200 200\"><circle cx=\"100\" cy=\"100\" r=\"76\" fill=\"none\" stroke=\"#eff1ed\" strokeWidth=\"25\"/>{[{color:'#779b7e',dash:211,offset:0},{color:'#b8c8a7',dash:130,offset:-215},{color:'#dfc7a5',dash:78,offset:-349},{color:'#e7e9e2',dash:45,offset:-431}].map(a=><circle key={a.color} cx=\"100\" cy=\"100\" r=\"76\" fill=\"none\" stroke={a.color} strokeWidth=\"25\" strokeDasharray={"'`${a.dash} 478`} strokeDashoffset={a.offset} transform="rotate(-90 100 100)"/> )}</svg><div className="donut-label"><span>Всего посещений</span><strong>24 892</strong><small><Icon name="arrow" size={12}/> 12,8% за месяц</small></div></div><div className="source-list">{[['"'#779b7e','Органический поиск','45,2%'],['#b8c8a7','Прямые переходы','28,4%'],['#dfc7a5','Социальные сети','16,8%'],['#e7e9e2','Другое','9,6%']].map(([c,n,p])=><div key={n}><span><i style={{background:c}}/>{n}</span><strong>{p}</strong></div>)}</div></>}
export function App(){
 const [widgets,setWidgets]=useState<Widget[]>(readLayout);const [editing,setEditing]=useState(false);const [drawer,setDrawer]=useState(false);const [period,setPeriod]=useState('month');const [query,setQuery]=useState('');const [nav,setNav]=useState('Обзор');const [toast,setToast]=useState('');const [notification,setNotification]=useState(false);const [profile,setProfile]=useState(false);const [menu,setMenu]=useState<string|null>(null);const [dragging,setDragging]=useState<string|null>(null);const [dropTarget,setDropTarget]=useState<string|null>(null);const [selectedOrder,setSelectedOrder]=useState<typeof transactions[0]|null>(null);const [allOrders,setAllOrders]=useState(false);const [mobileNav,setMobileNav]=useState(false);const searchRef=useRef<HTMLInputElement>(null);
 useEffect(()=>localStorage.setItem('forma-layout',JSON.stringify(widgets)),[widgets]);
 useEffect(()=>{if("'!toast)return;const timer=setTimeout(()=>setToast('"''),3500);return()=>clearTimeout(timer)},[toast]);
 useEffect(()=>{const listener=(e:KeyboardEvent)=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();searchRef.current?.focus()}if(e.key==='Escape'){setDrawer(false);setMenu(null);setProfile(false);setNotification(false);setSelectedOrder(null)}};window.addEventListener('keydown',listener);return()=>window.removeEventListener('keydown',listener)},[]);
 const reorder=(target:string)=>{if(dragging&&dragging"'!==target)setWidgets(old=>{const next=[...old];const from=next.findIndex(w=>w.id===dragging),to=next.findIndex(w=>w.id===target);next.splice(to,0,next.splice(from,1)[0]);return next});setDragging(null);setDropTarget(null)};
 const download=()=>{const rows=[['"'Номер заказа','Клиент','Дата','Сумма, ₽','Статус'],...transactions.map(t=>[t.id,t.name,t.date,t.amount,t.status])];const url=URL.createObjectURL(new Blob(['\\uFEFF'+rows.map(r=>r.join(';')).join('\\n')],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download='forma-report-june-2025.csv';a.click();URL.revokeObjectURL(url);setToast('Отчёт выгружен в CSV')};
 const addWidget=(type:string)=>{setWidgets(old=>[...old,{id:type+'-'+Date.now(),type,span:['sales','transactions'].includes(type)?8:['traffic','goal'].includes(type)?4:3}]);setToast('Виджет добавлен на дашборд');setDrawer(false)};
 const statData:Record<string,{value:string;growth:string;icon:IconName;index:number}>={revenue:{value:period==='week'?'324 850':'1 284 650',growth:'18,6',icon:'wallet',index:0},orders:{value:period==='week'?'462':'1 842',growth:'12,8',icon:'bag',index:1},customers:{value:period==='week'?'128':'648',growth:'8,2',icon:'users',index:2},conversion:{value:'3,62',growth:'2,4',icon:'chart',index:3},visitors:{value:'24 892',growth:'12,8',icon:'globe',index:1}};
 const renderWidget=(w:Widget)=>{if(statData[w.type]){const d=statData[w.type];return <><div className=\"stat-top\"><span>{widgetNames[w.type]}</span><Icon name={d.icon} size={18}/></div><div className=\"stat-value\">{w.type==='revenue'&&<span className=\"currency\">₽ </span>}{d.value}{w.type==='conversion'&&<span className=\"currency\"> %</span>}</div><div className=\"stat-bottom\"><div><span className=\"growth\"><Icon name=\"arrow\" size={12}/>{d.growth}%</span><span className=\"stat-comparison\">к прошлому периоду</span></div><Spark variant={d.index}/></div></>};
 if(w.type==='sales')return <RevenueChart period={period}/>;
 if(w.type==='traffic')return <Traffic/>;
 if(w.type==='goal')return <><div className=\"card-heading\"><div><h3>Большие планы. Ближе каждый день.</h3><p>Ваша цель по выручке на июнь</p></div><span className=\"goal-icon\"><Icon name=\"target\" size={21}/></span></div><div className=\"goal-amount\">1 284 650 <span>/ 1 500 000 ₽</span></div><div className=\"progress-track\"><div style={{width:'85.6%'}}/></div><div className=\"goal-progress\"><span>85,6% выполнено</span><strong>Осталось 215 350 ₽</strong></div><div className=\"goal-message\"><span>✦</span><p>Отличный темп"'! Вы на 18,6% впереди<br/>результата прошлого месяца.</p></div><button className="goal-link" onClick={()=>{setNav('"'Аналитика');setToast('Показаны показатели достижения цели')}}>Подробнее о результатах <Icon name=\"arrow\" size={16}/></button></>;
 return <><div className=\"card-heading\"><div><h3>{nav==='Клиенты'?'Ваши клиенты':'Последние заказы'}</h3><p>{nav==='Клиенты'?'Люди, которые выбирают ваш бизнес':'Каждый заказ — маленькая победа'}</p></div><button className=\"text-button\" onClick={()=>setAllOrders("'!allOrders)}>{allOrders?'"'Свернуть':'Все заказы'}<Icon name=\"chevron\" size={14}/></button></div><div className=\"table-scroll\"><table><thead><tr><th>Клиент</th><th>Заказ</th><th>Сумма</th><th>Статус</th><th/></tr></thead><tbody>{(allOrders?[...transactions,...transactions.map((t,i)=>({...t,id:"'`#FR-${1044-i}`,date:'"'28 июн, 2025'}))]:transactions).filter(t=>(t.name+t.email+t.id).toLowerCase().includes(query.toLowerCase())).map(t=><tr key={t.id} onClick={()=>setSelectedOrder(t)} tabIndex={0} onKeyDown={e=>e.key==='Enter'&&setSelectedOrder(t)}><td><div className=\"customer\"><span className={"'`avatar ${t.color}`}>{t.initials}</span><div><strong>{t.name}</strong><small>{t.email}</small></div></div></td><td className="order-id">{t.id}</td><td className="amount">{t.amount} ₽</td><td><span className={`status ${t.status==='"'Оплачен'?'paid':'pending'}"'`}><i/>{t.status}</span></td><td><Icon name="chevron" size={15}/></td></tr>)}</tbody></table>{query&&!transactions.some(t=>(t.name+t.email+t.id).toLowerCase().includes(query.toLowerCase()))&&<div className="no-results">По запросу «{query}» ничего не найдено</div>}</div></>;
 };
 const visibleWidgets=widgets.filter(w=>nav==='"'Аналитика'?['sales','traffic','conversion','visitors','revenue','goal'].includes(w.type):nav==='Заказы'?['orders','revenue','transactions'].includes(w.type):nav==='Клиенты'?['customers','conversion','traffic','transactions'].includes(w.type):true);
